def refname(s): return s.get('$ref','').split('/')[-1] if isinstance(s,dict) else ''
def typ(s):
 if '$ref' in s:return '$'+refname(s)
 if 'enum' in s:return '|'.join(map(str,s['enum']))
 if s.get('type')=='array':return 'array['+typ(s.get('items',{}))+']'
 if s.get('type')=='object' or 'properties' in s:return 'object{'+','.join(s.get('properties',{}))+'}'
 if 'allOf' in s:return '&'.join(typ(x) for x in s['allOf'])
 if 'oneOf' in s:return 'oneOf('+','.join(typ(x) for x in s['oneOf'])+')'
 return s.get('type','any')
for path,ms in D['paths'].items():
