func (a *App) ServeHTTP(w http.ResponseWriter,r *http.Request) {
	defer func(){if x:=recover();x!=nil{log.Printf("panic: %v\n%s",x,debug.Stack());writeError(w,fail(500,"internal_error","Internal server error"))}}()
	w.Header().Set("X-Content-Type-Options","nosniff")
	w.Header().Set("Referrer-Policy","same-origin")
	if r.URL.Path=="/ready" { if r.Method!="GET"{writeError(w,fail(405,"method_not_allowed","Method not allowed"));return};if a.client.Ping(r.Context(),nil)!=nil{writeJSON(w,503,map[string]any{"status":"starting"});return};writeJSON(w,200,map[string]any{"status":"ready"});return }
	if r.URL.Path=="/maps/bangalore.pmtiles" { http.ServeFile(w,r,"/opt/arena/map-assets/bangalore.pmtiles");return }
	if r.URL.Path=="/api/events" { a.handleEvents(w,r);return }
	if r.URL.Path=="/api/ui/bootstrap" { a.handleBootstrapHTTP(w,r);return }
	if strings.HasPrefix(r.URL.Path,"/api/read-sample-state/") { a.handleSampleStateHTTP(w,r,strings.TrimPrefix(r.URL.Path,"/api/read-sample-state/"));return }
	if strings.HasPrefix(r.URL.Path,"/api/read-user/") { a.handleReadUserHTTP(w,r,strings.TrimPrefix(r.URL.Path,"/api/read-user/"));return }
	if rt,ok:=a.routes()[r.URL.Path];ok { a.execute(w,r,rt);return }
	if strings.HasPrefix(r.URL.Path,"/api/"){writeError(w,fail(404,"not_found","Operation not found"));return}
	a.serveFrontend(w,r)
}

func (a *App) execute(w http.ResponseWriter,r *http.Request,rt route) {
	if r.Method!=rt.method { writeError(w,fail(405,"method_not_allowed","Method not allowed"));return }
	body,e:=decodeBody(r);if e!=nil{writeError(w,e);return}
	if e=validateContractBody(rt.operation,body);e!=nil{writeError(w,e);return}
	var actor *Actor
	if rt.operation!="authenticate_user" { actor,e=a.authenticate(r);if e!=nil{writeError(w,e);return};if e=a.authorize(actor,rt.operation);e!=nil{a.audit(r.Context(),actor,"permission_check",rt.operation,"",false,map[string]any{"code":e.Code});writeError(w,e);return} }
	data,status,e:=rt.handler(w,r,actor,body);if e!=nil{if actor!=nil{a.audit(r.Context(),actor,rt.operation,"operation","",false,map[string]any{"code":e.Code})};writeError(w,e);return}
	writeJSON(w,status,map[string]any{"data":data})
}

func decodeBody(r *http.Request) (bsonMap,*apiError) {
	defer r.Body.Close();d:=json.NewDecoder(io.LimitReader(r.Body,1<<20));d.UseNumber();var body bsonMap
	if err:=d.Decode(&body);err!=nil{return nil,fail(400,"invalid_json","Request body must be valid JSON")};if body==nil{return nil,fail(400,"invalid_json","Request body must be an object")}
	if d.Decode(&struct{}{})!=io.EOF{return nil,fail(400,"invalid_json","Request body must contain one JSON value")};return body,nil
}

var operationSchemas map[string]struct{Allowed,Required map[string]bool}
func loadContractSchemas() {
	operationSchemas=map[string]struct{Allowed,Required map[string]bool}{}
	b,e:=os.ReadFile("/workspace/app-setup/openapi.json");if e!=nil{return};var d map[string]any;if json.Unmarshal(b,&d)!=nil{return}
	paths,_:=d["paths"].(map[string]any);for _,pv:=range paths{methods,_:=pv.(map[string]any);for _,ov:=range methods{op,_:=ov.(map[string]any);id,_:=op["operationId"].(string);if id==""{continue};allowed,required:=map[string]bool{},map[string]bool{};rb,_:=op["requestBody"].(map[string]any);content,_:=rb["content"].(map[string]any);app,_:=content["application/json"].(map[string]any);schema,_:=app["schema"].(map[string]any);props,_:=schema["properties"].(map[string]any);for k:=range props{allowed[k]=true};if req,ok:=schema["required"].([]any);ok{for _,x:=range req{required[x.(string)]=true}};operationSchemas[id]=struct{Allowed,Required map[string]bool}{allowed,required}}}
