func (a *App) handleRoleWork(_ http.ResponseWriter,r *http.Request,actor *Actor,body bsonMap)(any,int,*apiError){role:=asString(body["role"]);if role==""{role=actor.ActiveRole};if role!=actor.ActiveRole{return nil,0,fail(403,"forbidden","Work views use the selected role")};pending,inProgress,completed:=bson.A{},bson.A{},bson.A{};put:=func(status string,item bson.M){switch status{case "received","completed","cancelled","delivered":completed=append(completed,item);case "accepted","in_progress","in_transit","picked_up","arrived","sealed","exception":inProgress=append(inProgress,item);default:pending=append(pending,item)}}
